+			name: "autogroup:internet without exit routes returns nil",
+			grant: Grant{
+				Sources:           Aliases{up("testuser@")},
+				Destinations:      Aliases{agp(string(AutoGroupInternet))},
+				InternetProtocols: allPorts,
+				Via:               []Tag{"tag:relay"},
+			},
